import React from 'react';
import { Play, Pause, RotateCcw, Activity, Shield, AlertTriangle, CheckCircle } from 'lucide-react';

const Dashboard = ({ isRunning, onStart, onStop, onReset, metrics }) => {
  const getHealthColor = (health) => {
    if (health >= 80) return '#10b981';
    if (health >= 50) return '#f59e0b';
    return '#ef4444';
  };

  const getHealthStatus = (health) => {
    if (health >= 80) return 'Optimal';
    if (health >= 50) return 'Degraded';
    return 'Critical';
  };

  return (
    <div className="dashboard-container">
      <div className="dashboard-controls">
        <button
          className={`control-btn ${isRunning ? 'stop-btn' : 'start-btn'}`}
          onClick={isRunning ? onStop : onStart}
        >
          {isRunning ? (
            <>
              <Pause size={20} />
              <span>Stop Simulation</span>
            </>
          ) : (
            <>
              <Play size={20} />
              <span>Start Simulation</span>
            </>
          )}
        </button>

        <button className="control-btn reset-btn" onClick={onReset}>
          <RotateCcw size={20} />
          <span>Reset System</span>
        </button>

        <div className={`status-indicator ${isRunning ? 'running' : 'stopped'}`}>
          <Activity size={20} />
          <span>{isRunning ? 'RUNNING' : 'STOPPED'}</span>
        </div>
      </div>

      <div className="metrics-grid">
        <div className="metric-card">
          <div className="metric-icon" style={{ background: '#3b82f6' }}>
            <Activity size={24} />
          </div>
          <div className="metric-content">
            <h3>Total Packets</h3>
            <p className="metric-value">{metrics.totalPackets}</p>
          </div>
        </div>

        <div className="metric-card">
          <div className="metric-icon" style={{ background: '#ef4444' }}>
            <Shield size={24} />
          </div>
          <div className="metric-content">
            <h3>Blocked Packets</h3>
            <p className="metric-value">{metrics.blockedPackets}</p>
          </div>
        </div>

        <div className="metric-card">
          <div className="metric-icon" style={{ background: '#f59e0b' }}>
            <AlertTriangle size={24} />
          </div>
          <div className="metric-content">
            <h3>Attacks Detected</h3>
            <p className="metric-value">{metrics.attacksDetected}</p>
          </div>
        </div>

        <div className="metric-card">
          <div className="metric-icon" style={{ background: getHealthColor(metrics.systemHealth) }}>
            <CheckCircle size={24} />
          </div>
          <div className="metric-content">
            <h3>System Health</h3>
            <p className="metric-value" style={{ color: getHealthColor(metrics.systemHealth) }}>
              {metrics.systemHealth}%
            </p>
            <span className="metric-status">{getHealthStatus(metrics.systemHealth)}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
